const fs = require\("fs"\);
const buf = fs.readFileSync\("tmp/asr-debug-b621e851.pcm"\);
const samples = new Int16Array\(buf.buffer, buf.byteOffset, buf.byteLength / 2\);
let max = 0, nonZero = 0;
for \(let i = 0; i < samples.length; i++\) {
  const abs = Math.abs\(samples[i]\);
  if \(abs > max\) max = abs;
  if \(abs > 0\) nonZero++;
}
console.log\("总样本数:", samples.length\);
console.log\("非零样本:", nonZero, "\(" + \(nonZero/samples.length*100\).toFixed\(1\) + "%\)"\);
console.log\("最大振幅:", max, "/ 32768"\);
console.log\("前20个样本:", Array.from\(samples.slice\(0, 20\)\)\);
